pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 logSeed) public {
        // Derive a deterministic but fuzzer-varied address from the seed
        address _log = address(uint160(uint256(keccak256(abi.encode(logSeed)))));
        // Deploy a helper that has code at _log to ensure the correct LogFile address succeeds
        // The buggy contract will set LogFile to _log+1, which may be an EOA or empty, causing revert
        vm.etch(_log, hex"60006000fd"); // minimal revert-on-call code at _log
        // Set up the contract
        c.SetLogFile(_log);
        c.Initialized();
        // The reference LogFile is _log (has code, reverts), buggy is _log+1 (EOA, no code, call succeeds?)
        // Actually we need to distinguish: reference uses _log, buggy uses _log+1.
        // If LogFile address has code, calls revert -> Collect fails. If no code, calls succeed.
        // We want reference to succeed (or behave in a consistent way) and buggy to fail.
        // Let's set up a helper where _log is a valid Log contract, and _log+1 is an EOA.
        // We can't deploy at a fuzzed address directly, but we can use vm.etch to give code to one.
        // Deploy a real Log contract and use its code.
        Log goodLog = new Log();
        vm.etch(_log, address(goodLog).code);
        // Now _log has valid Log code, _log+1 is an EOA (unless it collides, but probability is negligible)
        // Reference: LogFile = _log -> calls to AddMessage succeed.
        // Buggy: LogFile = _log+1 -> calls to AddMessage are low-level calls to an EOA, succeed silently?
        // Actually, c uses LogFile.AddMessage(...), which is a high-level contract call.
        // If LogFile is an EOA, the call succeeds but does nothing (no code), no revert.
        // But the bug is about a different address being set, not necessarily a revert.
        // The property: after SetLogFile, address(c.LogFile()) == _log. Buggy sets it to _log+1.
        // Wait, the error says "Member LogFile not found", meaning LogFile is private/internal?
        // Actually in contract C, LogFile is declared as `Log LogFile;` without visibility specifier, defaults to internal.
        // So there's NO public getter for LogFile. The previous test tried c.LogFile() and failed.
        // We cannot read LogFile directly. We must observe behavior: if LogFile is _log, sending a message via Put/Collect will call AddMessage on _log, which stores in History.
        // We can read LogFile's History through a helper.
        // Deploy a helper Log contract and set its address as _log.
        // After calling Put, check that History length increased.
        // Alternatively, use a helper that records if AddMessage was called.
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

