    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _log) public {
        // The bug mutates LogFile to address(uint160(_log) + 1), which is an arbitrary address without the Log contract code.
        // After initialization, any interaction with LogFile (e.g., Put) will fail in the buggy version but succeed in the reference.
        // We deploy the legitimate Log contract at _log, set it as LogFile, initialize, then attempt a Put.
        // In the reference, the call to LogFile.AddMessage inside Put succeeds.
        // In the buggy version, LogFile points to _log+1, which has no code, so the call reverts.
        vm.assume(_log != address(0));
        // deploy the real Log at _log using create2
        bytes32 salt = 0;
        // compute creation code for Log
        bytes memory logCode = type(Log).creationCode;
        address deployedLog;
        assembly {
            deployedLog := create2(0, add(logCode, 0x20), mload(logCode), salt)
        }
        // If deployedLog != _log, we cannot guarantee difference, skip this run
        vm.assume(deployedLog == _log);
        // Set up the contract
        c.SetLogFile(_log);
        c.Initialized();
        // Now attempt a Put, which calls LogFile.AddMessage. Reference succeeds, buggy reverts.
        bool ok;
        try c.Put{value: 1}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

