pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 lockTime, uint256 putAmount, uint256 collectAmount, uint256 minSum) public {
        // Keep domain wide but avoid overflow on balance addition
        vm.assume(putAmount < type(uint256).max / 2);
        vm.assume(collectAmount > 0);
        vm.assume(minSum < type(uint256).max / 2);
        vm.assume(collectAmount <= type(uint256).max / 2);
        // Ensure Put does not revert due to overflow of acc.balance (require ensures no overflow but we keep safe)
        vm.assume(putAmount > 0);
        vm.assume(putAmount + putAmount < type(uint256).max); // for any second put later

        address caller = address(0x1234);
        vm.deal(caller, putAmount * 2 + 1 ether);

        // Initialize and set MinSum
        vm.startPrank(address(this));
        c.SetMinSum(minSum);
        c.Initialized();
        vm.stopPrank();

        // Put with lockTime
        vm.prank(caller);
        c.Put{value: putAmount}(lockTime);

        // Ensure block.timestamp is less than unlockTime to make Collect revert in reference
        // unlockTime = block.timestamp + lockTime > block.timestamp always if lockTime > 0
        vm.assume(lockTime > 0);
        // Now timestamp < unlockTime, reference Collect should not change balance for any am
        // But we need balance >= MinSum and balance >= collectAmount to enter the if.
        // If these conditions are false, neither contract changes balance, test passes vacuously.
        // We must allow cases where these are true to distinguish.
        // Use assume to ensure collectAmount <= putAmount and putAmount >= minSum so we enter if in both.
        vm.assume(collectAmount <= putAmount);
        vm.assume(putAmount >= minSum);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller);

        // Attempt Collect
        vm.prank(caller);
        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = c.Acc(caller);

        // Reference: Collect only succeeds if block.timestamp > unlockTime; here it's false, so Collect either reverts or does nothing -> balance unchanged.
        // Buggy: Collect removes the amount even without unlockTime -> balance drops (if conditions met).
        // So invariant: balance remains unchanged iff reference behavior holds.
        assertTrue(balanceAfter == balanceBefore);
    }
}

